lickr Page URL'=>'URL da sua página do Flickr','Your Instagram Page URL'=>'URL da sua página do Instagram','Your Linkedin Page URL'=>'URL da sua página do Linkedin','Your Pinterest Page URL'=>'URL da sua página do Pinterest','Your Twitter Page URL'=>'URL da sua página do Twitter','Your Youtube Page URL'=>'URL da sua página do Youtube','and now has an average rating of'=>'e agora tem uma classificação média de','based on'=>'baseado em','https://blazzdev.com'=>'https://blazzdev.com','https://wordpress.org/plugins/rate-my-post/'=>'https://wordpress.org/plugins/rate-my-post/','reCAPTCHA v3 Secret Key'=>'Chave secreta reCAPTCHA v3','reCAPTCHA v3 Site Key'=>'Chave do site reCAPTCHA v3','reCaptcha is not configured correctly. Make sure you have inserted secret and site key in the security options'=>'O reCaptcha não está configurado corretamente. Verifique se você inseriu a chave secreta e a chave do site nas opções de segurança','vote(s)'=>'voto(s)','was rated'=>'foi avaliado']];
